const model=new CubeModel(),$=id=>document.getElementById(id),svg=$('graph'),canvas=$('cube'),ctx=canvas.getContext('2d');
let selected=-1,busy=false,animation=null,yaw=-.57,pitch=.46,hitPolys=[],drag=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const clusters=[[330,83],[510,164],[510,328],[330,407],[150,328],[150,164]];
const xy=slots.map(s=>[clusters[s.fi][0]+(s.j%3-1)*29,clusters[s.fi][1]+(Math.floor(s.j/3)-1)*29]);
function el(tag,attrs,parent=svg){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.appendChild(n);return n}
const lineEls=edges.map(([a,b])=>{let [x,y]=xy[a],[xx,yy]=xy[b],cross=slots[a].fi!==slots[b].fi;return el('path',{d:cross?`M${x},${y} Q330,245 ${xx},${yy}`:`M${x},${y} L${xx},${yy}`,fill:'none',stroke:cross?'#52647c':'#6b809b','stroke-width':cross?1:1.5,opacity:cross?.27:.48,class:'graph-edge'})});
faces.forEach((f,i)=>{let [x,y]=clusters[i],label=el('text',{x,y:y+(i===0?-47:i===3?55:-48),'text-anchor':'middle',class:'graph-label'});label.textContent=`${f.id} · ${f.name}`});
const nodes=slots.map((s,i)=>{const g=el('g',{class:'node',role:'button',tabindex:0,'aria-label':s.id});el('circle',{cx:xy[i][0],cy:xy[i][1],r:10,fill:faces[s.fi].color,stroke:'#141b25','stroke-width':3},g);g.addEventListener('click',()=>select(i));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(i)}});return g});
function select(i){selected=selected===i?-1:i;update();draw()}
function update(){nodes.forEach((g,i)=>{g.firstChild.setAttribute('fill',faces[model.colors[i]].color);g.firstChild.setAttribute('stroke',i===selected?'#ffffff':'#141b25');g.firstChild.setAttribute('stroke-width',i===selected?4:3);g.setAttribute('aria-label',`${slots[i].id}: цвет грани ${faces[model.colors[i]].id}`);g.setAttribute('aria-pressed',String(i===selected))});lineEls.forEach((n,i)=>{let [a,b]=edges[i],cross=slots[a].fi!==slots[b].fi,on=a===selected||b===selected;n.style.display=cross&&!$('edges').checked?'none':'';n.setAttribute('stroke',on?'#e6f6cf':cross?'#52647c':'#6b809b');n.setAttribute('opacity',on?1:selected<0?(cross?.27:.48):.12);n.setAttribute('stroke-width',on?2.4:cross?1:1.5)});$('status').textContent=model.solved?'Кубик собран':'Кубик перемешан';$('status').style.color=model.solved?'':'#bac8d9';$('moves').textContent=`Ходов: ${model.history.length}`;$('history').replaceChildren();if(!model.history.length)$('history').textContent='Пока без поворотов';model.history.slice(-60).forEach(m=>{let b=document.createElement('b');b.textContent=m;$('history').append(b)});$('history').scrollTop=9999;$('undo').disabled=busy||!model.history.length;document.querySelectorAll('.turns button,#shuffle,#reset').forEach(b=>b.disabled=busy);if(selected>=0){const s=slots[selected],f=faces[model.colors[selected]],near=edges.filter(e=>e.includes(selected)).map(e=>slots[e[0]===selected?e[1]:e[0]].id);$('selection').textContent=`${s.id} · ${faces[s.fi].name} · цвет ${f.id}`;$('neighbor-note').textContent=`Соседи: ${near.join(', ')}. Степень вершины: 4.`}else{$('selection').textContent='Выберите цветной узел на графе';$('neighbor-note').textContent='Каждая вершина имеет 4 соседа. Это граф поверхности, а не граф всех состояний кубика.'}}
function camera(p){return rotate(rotate(p,[0,1,0],yaw),[1,0,0],pitch)}
function draw(){const box=canvas.getBoundingClientRect(),w=box.width,h=box.height,dpr=devicePixelRatio||1;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const size=Math.min(w*.16,h*.165),project=p=>{let c=camera(p),k=7/(7-c[2]);return [w/2+c[0]*size*k,h*.46-c[1]*size*k,c[2]]};let polygons=[];slots.forEach((s,i)=>{const f=faces[s.fi],turn=animation&&dot(s.p,animation.axis)===1,tx=p=>turn?rotate(p,animation.axis,animation.angle):p,n=tx(s.n);if(camera(n)[2]<.025)return;const corners=[[-1,-1],[1,-1],[1,1],[-1,1]].map(([u,v])=>project(tx(add(s.q,add(scale(f.u,u*.463),scale(f.v,v*.463))))));polygons.push({i,corners,z:corners.reduce((a,p)=>a+p[2],0)/4})});polygons.sort((a,b)=>a.z-b.z);hitPolys=polygons;polygons.forEach(({i,corners})=>{ctx.beginPath();corners.forEach((p,j)=>j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=faces[model.colors[i]].color;ctx.fill();ctx.strokeStyle=i===selected?'#ffffff':'#090d14';ctx.lineWidth=i===selected?4:2;ctx.lineJoin='round';ctx.stroke();if(i===selected){let x=corners.reduce((a,p)=>a+p[0],0)/4,y=corners.reduce((a,p)=>a+p[1],0)/4;ctx.fillStyle='#142132';ctx.font='bold 14px monospace';ctx.textAlign='center';ctx.fillText(slots[i].id,x,y+5)}})}
async function move(m,record=true){const f=faces.find(f=>f.id===m[0]),direction=m.endsWith("'")?1:-1;if(!reduced)await new Promise(resolve=>{let start=performance.now();function frame(now){let t=Math.min(1,(now-start)/240);animation={axis:f.n,angle:direction*Math.PI/2*(t*t*(3-2*t))};draw();if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});animation=null;model.turn(m,record);update();draw()}
async function run(moves){if(busy)return false;if(!Array.isArray(moves)||moves.length>100||moves.some(m=>typeof m!=='string'||!/^[URFDLB]'?$/.test(m)))throw Error('Допустимо от 0 до 100 ходов U, R, F, D, L, B с необязательным штрихом.');busy=true;update();try{for(const m of moves)await move(m)}finally{busy=false;update()}return true}
for(const f of faces){let group=document.createElement('div');group.className='turn-pair';for(const inverse of [false,true]){let m=f.id+(inverse?"'":''),b=document.createElement('button');b.textContent=m;b.title=`${f.name}: ${inverse?'против':'по'} часовой стрелке`;b.setAttribute('aria-label',b.title);b.onclick=()=>run([m]);group.append(b)}$('turns').append(group);let span=document.createElement('span'),swatch=document.createElement('i');swatch.style.background=f.color;span.append(swatch,`${f.id} ${f.name}`);$('legend').append(span)}
$('edges').onchange=update;$('view').onclick=()=>{yaw=-.57;pitch=.46;draw()};$('reset').onclick=()=>{if(busy)return;model.reset();selected=-1;update();draw()};$('undo').onclick=async()=>{if(busy||!model.history.length)return;busy=true;const m=model.history.pop();update();try{await move(m.endsWith("'")?m[0]:m+"'",false)}finally{busy=false;update()}};$('shuffle').onclick=()=>{let seq=[],prev='';for(let i=0;i<20;i++){let ids='URFDLB'.split('').filter(x=>x!==prev),id=ids[Math.floor(Math.random()*ids.length)];prev=id;seq.push(id+(Math.random()<.5?"'":''))}run(seq)};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select,button')||e.repeat)return;let c=e.key.toUpperCase();if('URFDLB'.includes(c)&&c.length===1){e.preventDefault();run([c+(e.shiftKey?"'":'')])}});
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false}});canvas.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)drag.moved=true;yaw+=dx*.009;pitch=Math.max(-1.5,Math.min(1.5,pitch+dy*.009));drag.x=e.clientX;drag.y=e.clientY;draw()});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){let b=canvas.getBoundingClientRect(),x=e.clientX-b.left,y=e.clientY-b.top;for(const poly of [...hitPolys].reverse()){let inside=false,p=poly.corners;for(let i=0,j=p.length-1;i<p.length;j=i++){if((p[i][1]>y)!==(p[j][1]>y)&&x<(p[j][0]-p[i][0])*(y-p[i][1])/(p[j][1]-p[i][1])+p[i][0])inside=!inside}if(inside){select(poly.i);break}}}drag=null});canvas.addEventListener('pointercancel',()=>drag=null);new ResizeObserver(draw).observe(canvas);update();draw();
if(document.modelContext?.registerTool){const tool={name:'turn_rubik_cube',title:'Повернуть кубик Рубика',description:'Выполняет последовательность ходов и обновляет кубик и цветной граф.',inputSchema:{type:'object',properties:{moves:{type:'array',items:{type:'string',pattern:"^[URFDLB]'?$"},maxItems:100}},required:['moves'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||Object.keys(input).some(k=>k!=='moves'))throw Error('Ожидается объект moves');if(busy)throw Error('Дождитесь завершения текущих ходов');await run(input.moves);return {solved:model.solved,moves:model.history.length,colors:model.colors.map(c=>faces[c].id)}}};try{Promise.resolve(document.modelContext.registerTool(tool)).catch(console.warn)}catch(e){console.warn(e)}}
